const original = $('Normalize Event').first().json;
const raw = $json.choices?.[0]?.message?.content ?? '{}';
let ai;
try { ai = JSON.parse(raw); } catch { ai = { summary: raw }; }
return [{ json: { ...original, ai_status: 'Analyzed', ai_summary: ai.summary ?? null, ai_probability: ai.confidence ?? null, extracted_company: ai.company ?? null, extracted_contact: ai.contact ?? null, extracted_project: ai.project ?? null, extracted_value: ai.estimated_value ?? null, extracted_project_type: ai.project_type ?? null, ai_category: ai.category ?? null, ai_stage: ai.stage ?? null, ai_urgency: ai.urgency ?? null, next_action: ai.next_action ?? null, next_action_date: ai.next_action_date ?? null, ai_payload: ai } }];
